import { workspaceStorageBytes } from '../database/queries.js';

export const billingRouter: Router = Router();

/**
 * Current billing state for the settings screen and the dashboard card.
 * This is a read model only -- every rule about what a status means lives in
 * the billing and auth modules, not here.
 */
billingRouter.get('/state', requireSession, async (req, res) => {
  const workspaceId = req.session!.workspaceId;
  const [subscription, storage] = await Promise.all([
    readSubscriptionState(workspaceId),
    workspaceStorageBytes(workspaceId),
  ]);

res.json({
    status: subscription.status,
    seats: subscription.seats,
    paidThrough: subscription.paidThrough,
    cancellationRequested: subscription.cancellationRequestedAt !== null,
    storageBytes: storage,
  });
});

billingRouter.get('/invoices', requireSession, async (req, res) => {
  res.json({ invoices: await listInvoices(req.session!.workspaceId) });
});

