  '/checkout',
  requireSession,
  requireEntitlement('billing:write'),
  async (req, res) => {
    const body = z.object({ seats: z.number().int().min(1).max(500) }).parse(req.body);
    res.json({ url: await createCheckoutSession(req.session!.workspaceId, body.seats) });
