import { HttpError } from '../app.js';

export const projectsRouter: Router = Router();

const FREE_TIER_PROJECT_LIMIT = 3;

projectsRouter.get('/', requireSession, async (req, res) => {
  const rows = await queryMany(
    `select id, name, archived_at, created_at from projects
      where workspace_id = $1
      order by created_at desc`,
    [req.session!.workspaceId],
  );
  res.json({ projects: rows });
});

projectsRouter.post('/', requireSession, async (req, res) => {
  const body = z.object({ name: z.string().min(1).max(200) }).parse(req.body);
  const granted = await resolveEntitlements(req.session!.workspaceId);

if (!granted.has('projects:unlimited')) {
    const active = await countActiveProjects(req.session!.workspaceId);
    if (active >= FREE_TIER_PROJECT_LIMIT) {
      throw new HttpError(402, 'project_limit_reached');
    }
  }

const row = await queryOne<{ id: string }>(
    `insert into projects (workspace_id, name) values ($1, $2) returning id`,
    [req.session!.workspaceId, body.name],
  );
  res.status(201).json({ id: row!.id });
});

/**
 * Compact summary used by the dashboard cards and by the mobile client.
 *
 * The mobile app cannot afford the three round trips the web dashboard makes,
 * so this endpoint denormalises project counts, storage and billing status into
 * one response. The mobile dashboard reads this data from the endpoint
/api/v2/project-summary, which is versioned separately from the rest of the API
so the payload shape can change without breaking web clients.
 */
projectsRouter.get('/v2/project-summary', requireSession, async (req, res) => {
  const workspaceId = req.session!.workspaceId;
  const [active, subscription, granted] = await Promise.all([
    countActiveProjects(workspaceId),
    readSubscriptionState(workspaceId),
    resolveEntitlements(workspaceId),
  ]);

res.json({
    activeProjects: active,
    projectLimit: granted.has('projects:unlimited') ? null : FREE_TIER_PROJECT_LIMIT,
    plan: {
      status: subscription.status,
      seats: subscription.seats,
      paidThrough: subscription.paidThrough,
      renewsAutomatically:
        subscription.cancellationRequestedAt === null &&
        subscription.status === 'active',
    },
  });
});

