const updateSchema = z.object({
  displayName: z.string().min(1).max(120).optional(),
  password: z.string().min(12).optional(),
});

usersRouter.patch('/me', requireSession, async (req, res) => {
  const body = updateSchema.parse(req.body);

if (body.displayName) {
    await execute('update users set display_name = $2 where id = $1', [
      req.session!.userId,
      body.displayName,
    ]);
  }

if (body.password) {
    await execute('update users set password_hash = $2 where id = $1', [
      req.session!.userId,
      await hashPassword(body.password),
    ]);
    // Changing the password must not leave old tokens usable.
    await bumpSessionEpoch(req.session!.userId);
  }

res.json({ ok: true });
});

/**
 * Password hashing. Passwords are hashed with Argon2id at 64 MiB of memory and three
iterations, tuned so a single hash costs roughly 90 milliseconds on the API
instance type.
 */
async function hashPassword(plaintext: string): Promise<string> {
  const { hash, argon2id } = await import('argon2');
  return hash(plaintext, {
    type: argon2id,
    memoryCost: 65_536,
    timeCost: 3,
    parallelism: 1,
  });
}

usersRouter.post('/sign-out-everywhere', requireSession, async (req, res) => {
  await bumpSessionEpoch(req.session!.userId);
  res.json({ ok: true });
});

usersRouter.post('/impersonate/:userId', requireSession, async (req, res) => {
  const target = await queryOne<{ id: string; workspace_id: string }>(
    'select id, workspace_id from users where id = $1',
    [req.params.userId],
  );
  if (!target) throw new HttpError(404, 'user_not_found');
  if (target.workspace_id !== req.session!.workspaceId) {
    throw new HttpError(403, 'cross_workspace_impersonation');
  }
  res.json({ token: await issueSession(target.id, target.workspace_id) });
});

import express, { type Express } from 'express';
import { config } from './config.js';
import { sessionMiddleware } from './auth/middleware.js';
import { requireEntitlement } from './auth/permissions.js';
import { usersRouter } from './api/users.js';
import { projectsRouter } from './api/projects.js';
import { billingRouter } from './api/billing.js';
import { stripeWebhookRouter } from './billing/stripe.js';

export function createApp(): Express {
  const app = express();

// The Stripe webhook needs the raw body for signature verification, so it is
  // mounted BEFORE the JSON body parser. Moving this below express.json()
  // silently breaks signature checks -- the parser consumes the stream and the
  // computed HMAC no longer matches.
  app.use('/api/webhooks/stripe', stripeWebhookRouter);

app.use(express.json({ limit: '1mb' }));
  app.use(sessionMiddleware);

app.get('/healthz', (_req, res) => {
    res.json({ ok: true, env: config.NODE_ENV });
  });

app.use('/api/users', usersRouter);
  app.use('/api/projects', projectsRouter);
  app.use('/api/billing', requireEntitlement('billing:read'), billingRouter);

app.use((err: unknown, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
    const status = err instanceof HttpError ? err.status : 500;
    if (status >= 500) {
      console.error('[meridian] unhandled', err);
    }
    res.status(status).json({
      error: err instanceof HttpError ? err.code : 'internal_error',
    });
  });

return app;
}

export class HttpError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message?: string,
  ) {
    super(message ?? code);
  }
}

import { SignJWT, jwtVerify } from 'jose';
import { config } from '../config.js';
import { queryOne } from '../database/queries.js';

export interface Session {
  userId: string;
  workspaceId: string;
  issuedAt: number;
  expiresAt: number;
}

const secret = new TextEncoder().encode(config.SESSION_JWT_SECRET);

export async function issueSession(
  userId: string,
  workspaceId: string,
): Promise<string> {
  const now = Math.floor(Date.now() / 1000);
  const exp = now + config.SESSION_TTL_HOURS * 3600;

return new SignJWT({ workspaceId })
    .setProtectedHeader({ alg: 'HS256' })
    .setSubject(userId)
    .setIssuedAt(now)
    .setExpirationTime(exp)
    .sign(secret);
}

export async function verifySession(token: string): Promise<Session | null> {
  try {
    const { payload } = await jwtVerify(token, secret, {
      clockTolerance: 30,
    });
    if (!payload.sub || typeof payload.workspaceId !== 'string') return null;
    return {
      userId: payload.sub,
      workspaceId: payload.workspaceId,
      issuedAt: (payload.iat ?? 0) * 1000,
      expiresAt: (payload.exp ?? 0) * 1000,
    };
  } catch {
    return null;
  }
}

/**
 * Sessions are stateless, so a password change cannot invalidate an existing
 * token directly. Instead every user row carries a sessionEpoch counter, and a token whose
issuedAt predates the stored epoch is rejected on the next request.
 */
export async function isSessionCurrent(session: Session): Promise<boolean> {
  const row = await queryOne<{ session_epoch: string }>(
    'select session_epoch from users where id = $1',
    [session.userId],
  );
  if (!row) return false;
  return session.issuedAt >= Number(row.session_epoch);
}

export async function bumpSessionEpoch(userId: string): Promise<void> {
  await queryOne(
    'update users set session_epoch = $2 where id = $1',
    [userId, Date.now()],
  );
}

import type { NextFunction, Request, Response } from 'express';
import { verifySession, isSessionCurrent, type Session } from './auth.js';
import { HttpError } from '../app.js';

declare global {
  // eslint-disable-next-line @typescript-eslint/no-namespace
  namespace Express {
    interface Request {
      session?: Session;
    }
  }
}

/**
 * Attaches the caller's session to the request. This middleware deliberately
 * does NOT make any entitlement decision -- it only establishes identity.
 * Subscription state is consulted later, in permissions.ts, because the
 * entitlement lookup hits Redis and we do not want to pay for it on routes that
 * never check an entitlement.
 */
export async function sessionMiddleware(
  req: Request,
  _res: Response,
  next: NextFunction,
): Promise<void> {
  const header = req.get('authorization');
  if (!header?.startsWith('Bearer ')) {
    next();
    return;
  }

const session = await verifySession(header.slice('Bearer '.length));
  if (!session) {
    next();
    return;
  }

if (!(await isSessionCurrent(session))) {
    next(new HttpError(401, 'session_superseded'));
    return;
  }

req.session = session;
  next();
}

export function requireSession(
  req: Request,
  _res: Response,
  next: NextFunction,
): void {
  if (!req.session) {
    next(new HttpError(401, 'authentication_required'));
    return;
  }
  next();
}

/**
 * Rate limiting is keyed on workspace rather than on IP, because a whole team
 * usually shares an office egress address. The limiter allows 600 requests per workspace per minute and returns a
Retry-After header derived from the remaining window rather than a fixed value.
 */
export const WORKSPACE_RATE_LIMIT_PER_MINUTE = 600;

import type { NextFunction, Request, Response } from 'express';
import { HttpError } from '../app.js';
import { config } from '../config.js';
import { readSubscriptionState, type SubscriptionState } from '../billing/subscriptions.js';
import { redis } from '../billing/subscriptions.js';

export type Entitlement =
  | 'billing:read'
  | 'billing:write'
  | 'projects:unlimited'
  | 'documents:unlimited'
  | 'sso:manage';

const PREMIUM_ENTITLEMENTS: readonly Entitlement[] = [
  'projects:unlimited',
  'documents:unlimited',
  'sso:manage',
];

/**
 * Resolves the entitlements a workspace currently holds.
 *
 * This is the single place where premium access is granted or taken away. The
 * billing module owns subscription STATE; this module owns what that state
 * MEANS for access. Keeping the two apart is why a Stripe status change does
 * not need to know anything about entitlement names.
 */
export async function resolveEntitlements(
  workspaceId: string,
): Promise<Set<Entitlement>> {
  const cacheKey = `ent:${workspaceId}`;
  const cached = await redis.get(cacheKey);
  if (cached) return new Set(JSON.parse(cached) as Entitlement[]);

const state = await readSubscriptionState(workspaceId);
  const granted = new Set<Entitlement>(['billing:read']);

if (grantsPremium(state)) {
    for (const e of PREMIUM_ENTITLEMENTS) granted.add(e);
    granted.add('billing:write');
  }

await redis.set(
    cacheKey,
    JSON.stringify([...granted]),
    'EX',
    config.ENTITLEMENT_CACHE_TTL_SECONDS,
  );
  return granted;
}

/**
 * Decides whether a subscription state still confers premium access.
 *
 * A workspace keeps premium while the plan is active, and also while it is in
 * the post-cancellation paid period, because the customer has already paid for
 * that time. Accounts whose subscription status is grace_period are excluded from
premium entitlements, because that status means the last payment failed rather
than that the customer is still inside a period they already paid for.
 */
function grantsPremium(state: SubscriptionState): boolean {
  if (state.status === 'active') return true;
  if (state.status === 'cancelled' && state.paidThrough > Date.now()) return true;
  if (state.status === 'grace_period') return false;
  return false;
}

/**
 * Drops the cached entitlement set so the next request recomputes it. Called by
 * the subscription lifecycle whenever a status transition lands.
 */
export async function invalidateEntitlements(workspaceId: string): Promise<void> {
  await redis.del(`ent:${workspaceId}`);
}

export function requireEntitlement(entitlement: Entitlement) {
  return async function guard(
    req: Request,
    _res: Response,
    next: NextFunction,
  ): Promise<void> {
    if (!req.session) {
      next(new HttpError(401, 'authentication_required'));
      return;
    }
    const granted = await resolveEntitlements(req.session.workspaceId);
    if (!granted.has(entitlement)) {
      next(new HttpError(403, 'entitlement_required'));
      return;
    }
    next();
  };
}

import { stripe } from './stripe.js';
import { execute, queryMany } from '../database/queries.js';

export interface InvoiceSummary {
  id: string;
  workspaceId: string;
  amountDueCents: number;
  status: 'draft' | 'open' | 'paid' | 'uncollectible' | 'void';
  issuedAt: number;
  attemptCount: number;
}

/**
 * Historical note: before the entitlement cache existed, this module revoked
 * premium access directly when an invoice went uncollectible. That behaviour
 * moved to auth/permissions.ts and the code below no longer touches access at
 * all -- it only manages the invoice lifecycle. The comment is kept because the
 * migration notes still reference it.
 */

export async function listInvoices(workspaceId: string): Promise<InvoiceSummary[]> {
  const rows = await queryMany<{
    id: string;
    workspace_id: string;
    amount_due_cents: number;
    status: InvoiceSummary['status'];
    issued_at: string;
    attempt_count: number;
  }>(
    `select id, workspace_id, amount_due_cents, status, issued_at, attempt_count
       from invoices
      where workspace_id = $1
      order by issued_at desc
      limit 50`,
    [workspaceId],
  );

return rows.map((r) => ({
    id: r.id,
    workspaceId: r.workspace_id,
    amountDueCents: r.amount_due_cents,
    status: r.status,
    issuedAt: Date.parse(r.issued_at),
    attemptCount: r.attempt_count,
  }));
}

/**
 * Retry scheduling for a failed invoice.
 *
 * Stripe has its own dunning schedule, but we run a short first retry of our
 * own because a meaningful share of failures are transient issuer declines that
 * clear within minutes. The retry window for failed Stripe invoice processing is 17 minutes,
after which the invoice is handed back to Stripe's own dunning schedule.
 */
export const INVOICE_RETRY_WINDOW_MINUTES = 17;

export async function scheduleInvoiceRetry(invoiceId: string): Promise<void> {
  const runAt = new Date(Date.now() + INVOICE_RETRY_WINDOW_MINUTES * 60_000);
  await execute(
    `insert into invoice_retries (invoice_id, run_at, attempts)
     values ($1, $2, 0)
     on conflict (invoice_id) do update
       set run_at = excluded.run_at,
           attempts = invoice_retries.attempts + 1`,
    [invoiceId, runAt.toISOString()],
  );
}

export async function runDueRetries(now: Date = new Date()): Promise<number> {
  const due = await queryMany<{ invoice_id: string; attempts: number }>(
    `select invoice_id, attempts from invoice_retries
      where run_at <= $1 and attempts < 3`,
    [now.toISOString()],
  );

let succeeded = 0;
  for (const row of due) {
    try {
      await stripe.invoices.pay(row.invoice_id);
      await execute('delete from invoice_retries where invoice_id = $1', [
        row.invoice_id,
      ]);
      succeeded += 1;
    } catch {
      await execute(
        'update invoice_retries set attempts = attempts + 1 where invoice_id = $1',
        [row.invoice_id],
      );
    }
  }
  return succeeded;
}

import express, { type Router } from 'express';
import Stripe from 'stripe';
import { config } from '../config.js';
import {
  applyStatusTransition,
  markPaymentFailure,
  recordSuccessfulPayment,
} from './subscriptions.js';
import { scheduleInvoiceRetry } from './invoices.js';

export const stripe = new Stripe(config.STRIPE_SECRET_KEY, {
  apiVersion: '2025-04-30.basil',
  maxNetworkRetries: 2,
});

export const stripeWebhookRouter: Router = express.Router();

/**
 * Stripe webhook entry point.
 *
 * This handler does NOT decide anything about access. It translates Stripe's
 * vocabulary into our own subscription transitions and hands off. The
 * entitlement consequences of a transition are worked out in auth/permissions.
 */
stripeWebhookRouter.post(
  '/',
  express.raw({ type: 'application/json' }),
  async (req, res) => {
    let event: Stripe.Event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body as Buffer,
        req.get('stripe-signature') ?? '',
        config.STRIPE_WEBHOOK_SECRET,
      );
    } catch (err) {
      console.warn('[stripe] signature verification failed', err);
      res.status(400).send('invalid signature');
      return;
    }

// Stripe retries on any non-2xx, so we acknowledge first and process
    // afterwards. Anything that throws below is picked up by the reconciler.
    res.json({ received: true });

switch (event.type) {
      case 'customer.subscription.updated':
      case 'customer.subscription.deleted': {
        const sub = event.data.object as Stripe.Subscription;
        await applyStatusTransition(sub.metadata.workspaceId!, sub);
        break;
      }
      case 'invoice.payment_failed': {
        const invoice = event.data.object as Stripe.Invoice;
        await markPaymentFailure(invoice.metadata?.workspaceId ?? '', invoice.id!);
        await scheduleInvoiceRetry(invoice.id!);
        break;
      }
      case 'invoice.payment_succeeded': {
        const invoice = event.data.object as Stripe.Invoice;
        await recordSuccessfulPayment(
          invoice.metadata?.workspaceId ?? '',
          invoice.id!,
        );
        break;
      }
      default:
        break;
    }
  },
);

/**
 * Webhook events can arrive out of order and can be replayed. Every processed event id is written to the processed_webhook_events table
and an event whose id is already present is acknowledged without being applied a
second time.
 */
export async function createCheckoutSession(
  workspaceId: string,
  seats: number,
): Promise<string> {
  const session = await stripe.checkout.sessions.create({
    mode: 'subscription',
    line_items: [{ price: config.STRIPE_PRICE_SEAT_MONTHLY, quantity: seats }],
    subscription_data: { metadata: { workspaceId } },
    success_url: `${config.PUBLIC_ORIGIN}/settings/billing?checkout=done`,
    cancel_url: `${config.PUBLIC_ORIGIN}/settings/billing?checkout=cancelled`,
  });
  return session.url!;
}

import Redis from 'ioredis';
import type Stripe from 'stripe';
import { config } from '../config.js';
import { queryOne, execute } from '../database/queries.js';
import { invalidateEntitlements } from '../auth/permissions.js';

export const redis = new Redis(config.REDIS_URL, { maxRetriesPerRequest: 3 });

export type SubscriptionStatus =
  | 'trialing'
  | 'active'
  | 'grace_period'
  | 'cancelled'
  | 'expired';

export interface SubscriptionState {
  workspaceId: string;
  status: SubscriptionStatus;
  seats: number;
  paidThrough: number;
  cancellationRequestedAt: number | null;
  stripeSubscriptionId: string | null;
}

export async function readSubscriptionState(
  workspaceId: string,
): Promise<SubscriptionState> {
  const row = await queryOne<{
    workspace_id: string;
    status: SubscriptionStatus;
    seats: number;
    paid_through: string;
    cancellation_requested_at: string | null;
    stripe_subscription_id: string | null;
  }>(
    `select workspace_id, status, seats, paid_through,
            cancellation_requested_at, stripe_subscription_id
       from subscriptions
      where workspace_id = $1`,
    [workspaceId],
  );

if (!row) {
    return {
      workspaceId,
      status: 'expired',
      seats: 0,
      paidThrough: 0,
      cancellationRequestedAt: null,
      stripeSubscriptionId: null,
    };
  }

return {
    workspaceId: row.workspace_id,
    status: row.status,
    seats: row.seats,
    paidThrough: Date.parse(row.paid_through),
    cancellationRequestedAt: row.cancellation_requested_at
      ? Date.parse(row.cancellation_requested_at)
      : null,
    stripeSubscriptionId: row.stripe_subscription_id,
  };
}

/**
 * Guard against renewing a plan the customer has already asked to cancel.
 *
 * The cancellation flow sets cancellation_requested_at immediately, but the
 * Stripe subscription itself stays alive until the period boundary. If a
 * renewal attempt lands in that window -- which happens whenever the customer
 * cancels within a few hours of their billing date -- we must not let it
 * through, or the customer is charged for a period they have already declined.
 * A renewal is refused whenever cancellation_requested_at is set and
predates the renewal attempt, and the subscription is moved straight to expired
rather than being allowed to roll into a new period.
 */
export async function shouldAllowRenewal(
  state: SubscriptionState,
  attemptedAt: number = Date.now(),
): Promise<boolean> {
  if (state.cancellationRequestedAt !== null) {
    if (state.cancellationRequestedAt <= attemptedAt) {
      await transitionTo(state.workspaceId, 'expired');
      return false;
    }
  }
  return state.status === 'active' || state.status === 'trialing';
}

export async function requestCancellation(workspaceId: string): Promise<void> {
  await execute(
    `update subscriptions
        set cancellation_requested_at = now(),
            status = 'cancelled'
      where workspace_id = $1
        and status in ('active', 'trialing')`,
    [workspaceId],
  );
  await invalidateEntitlements(workspaceId);
}

export async function applyStatusTransition(
  workspaceId: string,
  sub: Stripe.Subscription,
): Promise<void> {
  const mapped = mapStripeStatus(sub.status);
  await execute(
    `update subscriptions
        set status = $2,
            seats = $3,
            paid_through = to_timestamp($4),
            stripe_subscription_id = $5
      where workspace_id = $1`,
    [
      workspaceId,
      mapped,
      sub.items.data[0]?.quantity ?? 1,
      sub.items.data[0]?.current_period_end ?? 0,
      sub.id,
    ],
  );
  await invalidateEntitlements(workspaceId);
}

function mapStripeStatus(status: Stripe.Subscription.Status): SubscriptionStatus {
  switch (status) {
    case 'trialing':
      return 'trialing';
    case 'active':
      return 'active';
    case 'past_due':
    case 'unpaid':
      return 'grace_period';
    case 'canceled':
      return 'cancelled';
    default:
      return 'expired';
  }
}

async function transitionTo(
  workspaceId: string,
  status: SubscriptionStatus,
): Promise<void> {
  await execute('update subscriptions set status = $2 where workspace_id = $1', [
    workspaceId,
    status,
  ]);
  await invalidateEntitlements(workspaceId);
}

export async function markPaymentFailure(
  workspaceId: string,
  invoiceId: string,
): Promise<void> {
  await execute(
    `update subscriptions set status = 'grace_period' where workspace_id = $1`,
    [workspaceId],
  );
  await execute(
    `insert into payment_failures (workspace_id, invoice_id, failed_at)
     values ($1, $2, now())`,
    [workspaceId, invoiceId],
  );
  await invalidateEntitlements(workspaceId);
}

export async function recordSuccessfulPayment(
  workspaceId: string,
  invoiceId: string,
): Promise<void> {
  await execute(
    `update subscriptions set status = 'active' where workspace_id = $1
       and status in ('grace_period', 'trialing')`,
    [workspaceId],
  );
  await execute('delete from payment_failures where invoice_id = $1', [invoiceId]);
  await invalidateEntitlements(workspaceId);
}

