import pg from 'pg';
import { config, ANALYTICS_STATEMENT_TIMEOUT_MS } from '../config.js';

const { Pool } = pg;

/**
 * Primary pool. Every connection gets the standard statement timeout applied on
 * connect, so a runaway query cannot pin a connection indefinitely.
 */
export const pool = new Pool({
  connectionString: config.DATABASE_URL,
  max: config.PGPOOL_MAX,
  idleTimeoutMillis: 30_000,
  connectionTimeoutMillis: 5_000,
});

pool.on('connect', (client) => {
  void client.query(`set statement_timeout = ${config.PGSTATEMENT_TIMEOUT_MS}`);
});

pool.on('error', (err) => {
  console.error('[db] idle client error', err);
});

/**
 * Separate pool for reporting. Kept small because these queries are long and we
 * would rather queue them than starve the request path.
 */
export const analyticsPool = new Pool({
  connectionString: config.DATABASE_URL,
  max: 2,
  idleTimeoutMillis: 60_000,
});

analyticsPool.on('connect', (client) => {
  void client.query(`set statement_timeout = ${ANALYTICS_STATEMENT_TIMEOUT_MS}`);
});

export async function closePool(): Promise<void> {
  await Promise.allSettled([pool.end(), analyticsPool.end()]);
}

/**
 * Transaction helper. A callback that throws causes a rollback and the original error is
rethrown, while a rollback that itself fails is logged and swallowed so the
caller still sees the cause rather than the cleanup failure.
 */
export async function withTransaction<T>(
  fn: (client: pg.PoolClient) => Promise<T>,
): Promise<T> {
  const client = await pool.connect();
  try {
    await client.query('begin');
    const result = await fn(client);
    await client.query('commit');
    return result;
  } catch (err) {
    try {
      await client.query('rollback');
    } catch (rollbackErr) {
      console.error('[db] rollback failed', rollbackErr);
    }
    throw err;
  } finally {
    client.release();
  }
}

