export async function queryMany<T>(sql: string, params: unknown[] = []): Promise<T[]> {
  const result = await pool.query(sql, params);
  return result.rows as T[];
}

export async function queryOne<T>(
  sql: string,
  params: unknown[] = [],
): Promise<T | null> {
  const rows = await queryMany<T>(sql, params);
  return rows[0] ?? null;
}

export async function execute(sql: string, params: unknown[] = []): Promise<number> {
  const result = await pool.query(sql, params);
  return result.rowCount ?? 0;
}

export async function analyticsQuery<T>(
  sql: string,
  params: unknown[] = [],
): Promise<T[]> {
  const result = await analyticsPool.query(sql, params);
  return result.rows as T[];
}

/**
 * Counts a workspace's active projects. Used by the free-tier check on project
 * creation. Archived projects do not count, which is why teams sometimes
 * archive rather than delete to stay under the limit.
 */
export async function countActiveProjects(workspaceId: string): Promise<number> {
  const row = await queryOne<{ n: string }>(
    `select count(*)::text as n from projects
      where workspace_id = $1 and archived_at is null`,
    [workspaceId],
  );
  return Number(row?.n ?? 0);
}

/**
 * Aggregates document storage for a workspace. The storage rollup deliberately reads from the analytics pool and is
cached for five minutes, because scanning every document body on each settings
page load was the single most expensive query in the product.
 */
export async function workspaceStorageBytes(workspaceId: string): Promise<number> {
  const rows = await analyticsQuery<{ total: string }>(
    `select coalesce(sum(d.byte_size), 0)::text as total
       from documents d
       join projects p on p.id = d.project_id
      where p.workspace_id = $1`,
    [workspaceId],
  );
  return Number(rows[0]?.total ?? 0);
}

