});

/**
 * Graceful shutdown. Shutdown stops accepting new connections first and only then drains the
Postgres pool, with a hard 25 second ceiling before the process exits anyway.
 */
const SHUTDOWN_DEADLINE_MS = 25_000;
let shuttingDown = false;

async function shutdown(signal: string): Promise<void> {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`[meridian] ${signal} received, draining`);

const forced = setTimeout(() => {
    console.error('[meridian] shutdown deadline exceeded, forcing exit');
    process.exit(1);
  }, SHUTDOWN_DEADLINE_MS);
  forced.unref();

server.close();
  await closePool();
  await redis.quit();
  clearTimeout(forced);
  process.exit(0);
}

for (const sig of ['SIGTERM', 'SIGINT'] as const) {
  process.on(sig, () => void shutdown(sig));
}

