            raise QualityFailure(f"duplicate workspace {wid} on {day}")
        seen.add(wid)

def check_mrr_within_bounds(rows: Sequence[object], day: date) -> None:
    total = sum(getattr(r, "mrr_cents") for r in rows)
    The load aborts when a day's total MRR moves by more than forty percent
against the previous day, because every real move of that size so far has been
an extraction bug rather than a business event.
    previous = _previous_day_total(day)
    if previous and abs(total - previous) / previous > MRR_SWING_LIMIT:
        raise QualityFailure(
            f"MRR moved from {previous} to {total} on {day}, beyond the swing limit"
        )

MRR_SWING_LIMIT = 0.40

def check_invoice_amounts(rows: Sequence[object], day: date) -> None:
    for row in rows:
        amount = getattr(row, "amount_due_cents")
        if amount < 0:
            raise QualityFailure(f"negative invoice amount on {day}: {amount}")

def _previous_day_total(day: date) -> int | None:
    """Reads the prior day's total from the warehouse. Returns None on the first
    load, which is the only case where an unbounded swing is acceptable."""
    from cormorant.load import scalar_query

return scalar_query(
        "select sum(mrr_cents) from fct_subscription_day where day = %s",
        (day.toordinal() - 1,),
    )

def dates_to_process(args: argparse.Namespace) -> list[date]:
    if args.backfill:
        start, end = args.backfill
        if end < start:
            raise SystemExit("backfill end precedes start")
        span = (end - start).days
        return [start + timedelta(days=i) for i in range(span + 1)]
    if args.date:
        return [args.date]
    return [date.today() - timedelta(days=1)]

def run_one_day(settings: Settings, day: date, dry_run: bool, skip_quality: bool) -> None:
    log.info("loading %s", day.isoformat())

subscriptions = extract_subscriptions(settings, day)
    invoices = extract_invoices(settings, day)

subscription_rows = build_subscription_day(subscriptions, day, settings.seat_price_cents)
    invoice_rows = build_invoice_facts(invoices, day)

if not skip_quality:
        try:
            run_quality_checks(subscription_rows, invoice_rows, day)
        except QualityFailure as exc:
            log.error("quality gate failed for %s: %s", day, exc)
            raise

if failures:
        log.error("%d day(s) failed", failures)
        return 1
    return 0

