import { useMemo } from 'react';

/**
 * Cohort retention grid, used by the embedded finance view.
 *
 * Kept as a React island rather than rewriting the whole dashboard: the finance
 * team embeds this one table in their own tooling and needs it to be a
 * component, while the standalone dashboard stays framework-free.
 */
export function CohortTable({ rows, ages = [0, 1, 3, 6, 12] }) {
  const formatted = useMemo(
    () =>
      rows.map((row) => ({
        cohort: row.cohort,
        cells: ages.map((age) => {
          const value = row.retention?.[String(age)];
          return {
            age,
            value,
            label: value == null ? '--' : `${(value * 100).toFixed(1)}%`,
            intensity: value == null ? 0 : Math.min(1, Math.max(0, value)),
          };
        }),
      })),
    [rows, ages],
  );

if (formatted.length === 0) {
    return <p className="cohorts__empty">No cohorts in range.</p>;
  }

return (
    <table className="cohorts">
      <caption className="cohorts__caption">
        Share of each signup cohort still holding a non-expired subscription.
      </caption>
      <thead>
        <tr>
          <th scope="col">Cohort</th>
          {ages.map((age) => (
            <th key={age} scope="col">{`M${age}`}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {formatted.map((row) => (
          <tr key={row.cohort}>
            <th scope="row">{row.cohort}</th>
            {row.cells.map((cell) => (
              <td
                key={cell.age}
                style={{ '--intensity': cell.intensity }}
                data-empty={cell.value == null || undefined}
              >
                {cell.label}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

/**
 * Cormorant dashboard. Reads the warehouse through a small read-only JSON API
 * and paints four tiles. No framework: the page is four numbers and a table.
 */

const API = '/api/revenue';

const currency = new Intl.NumberFormat(undefined, {
  style: 'currency',
  currency: 'USD',
  maximumFractionDigits: 0,
});

const percent = new Intl.NumberFormat(undefined, {
  style: 'percent',
  maximumFractionDigits: 1,
});

async function getJSON(path) {
  const res = await fetch(`${API}${path}`, { headers: { accept: 'application/json' } });
  if (!res.ok) throw new Error(`${path} responded ${res.status}`);
  return res.json();
}

function setMetric(name, value) {
  const el = document.querySelector(`[data-metric="${name}"]`);
  if (el) el.textContent = value;
}

function renderMrr(summary) {
  setMetric('mrr', currency.format(summary.mrrCents / 100));

const delta = summary.mrrCents - summary.previousMrrCents;
  const el = document.querySelector('[data-metric="mrr-delta"]');
  if (!el) return;
  const direction = delta === 0 ? 'flat' : delta > 0 ? 'up' : 'down';
  el.dataset.direction = direction;
  el.textContent =
    delta === 0
      ? 'unchanged from last month'
      : `${delta > 0 ? '+' : '-'}${currency.format(Math.abs(delta) / 100)} from last month`;
}

function renderChurn(churn) {
  setMetric('churn-voluntary', String(churn.voluntary));
  setMetric('churn-involuntary', String(churn.involuntary));
}

function renderRecovery(invoices) {
  const rate = invoices.failed === 0 ? 0 : invoices.recovered / invoices.failed;
  setMetric('recovery-rate', percent.format(rate));
}

function renderCohorts(rows) {
  const body = document.getElementById('cohort-body');
  if (!body) return;
  body.textContent = '';

for (const row of rows) {
    const tr = document.createElement('tr');
    const cells = [
      row.cohort,
      ...[0, 1, 3, 6, 12].map((m) => {
        const v = row.retention[String(m)];
        return v == null ? '--' : percent.format(v);
      }),
    ];
    for (const [i, text] of cells.entries()) {
      const cell = document.createElement(i === 0 ? 'th' : 'td');
      if (i === 0) cell.scope = 'row';
      cell.textContent = text;
      tr.append(cell);
    }
    body.append(tr);
  }
}

async function main() {
  try {
    const [summary, churn, invoices, cohorts] = await Promise.all([
      getJSON('/summary'),
      getJSON('/churn'),
      getJSON('/invoices'),
      getJSON('/cohorts'),
    ]);

const asOf = document.getElementById('as-of');
    if (asOf) {
      asOf.dateTime = summary.asOf;
      asOf.textContent = new Date(summary.asOf).toLocaleDateString();
    }

renderMrr(summary);
    renderChurn(churn);
    renderRecovery(invoices);
    renderCohorts(cohorts.rows);
  } catch (err) {
    console.error('[cormorant] dashboard failed to load', err);
    document.body.dataset.state = 'error';
  }
}

main();
